package com.univmar.customer.api;
import com.univmar.customer.domain.CustomerType; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.data.domain.Page;
public final class CustomerDtos { private CustomerDtos(){} public record ContactInput(@NotBlank String name,String role,@Email String email,String phone){} public record AddressInput(@NotBlank String label,@NotBlank String line1,String line2,String city,String country,String postalCode){} public record CustomerInput(@NotNull CustomerType type,@NotBlank String name,String companyName,@Email String email,String phone,String notes,List<@Valid ContactInput> contacts,List<@Valid AddressInput> addresses){} public record Contact(UUID id,String name,String role,String email,String phone){} public record Address(UUID id,String label,String line1,String line2,String city,String country,String postalCode){} public record CustomerResponse(UUID id,CustomerType type,String name,String companyName,String email,String phone,String notes,boolean active,List<Contact> contacts,List<Address> addresses){} public record CustomerPage(List<CustomerResponse> content,int page,int size,long totalElements,int totalPages){public static CustomerPage from(Page<CustomerResponse> page){return new CustomerPage(page.getContent(),page.getNumber(),page.getSize(),page.getTotalElements(),page.getTotalPages());}} }
